"""One-off: bring DATA_REGISTER, FACTOR_INVENTORY and VALIDATION_SAMPLE in line with batch 4 (parcels, planning authority, water network, quality registry)."""
from pathlib import Path
def edit(path, fn):
    p = Path(path); s = p.read_text(encoding="utf-8"); s2 = fn(s); p.write_text(s2, encoding="utf-8")

def reg(s):
    anchor = "| **Road routing** |"
    assert s.count(anchor) == 1
    new = ("| **Survey-parcel outlines** | TGRAC `Bhunaksha_Cadastral` layer 0 'Cadastral 2.5m' — `p31` → `web/data/parcels/*.json` (145 lazy tiles of 0.03°) | 47,249 parcel records (42,980 unique, 216 villages); service document created 2025-04-19; survey date and accuracy not published | VERIFIED: every tile holds exactly the parcels the server counts; matcher tested on 592 real parcels and on synthetic neighbours, overlaps, flagged numbers and gaps | Verify | `SNo` is a village serial, NOT a survey number (`Parcel_num` is); only filled `Parcel_num` polygons kept; old city core has only a placeholder; outlines are survey numbers (median 0.77 ha), not house plots; owner fields never requested |\n"
           "| **Prohibitory-category parcels** | TGRAC `Bhunaksha` layer 0 'ULB_Cadastral_Prohibited' — `p31` → `web/data/prohib.json` | 656 parcels in the box; service created 2025-04-19 | PARTIALLY VERIFIED: all 656 join onto the cadastral parcels by village and number; legal basis and date undocumented | Verify | quoted as recorded and never as the legal prohibited-property register |\n"
           "| **Planning-authority areas** | TGRAC `HMDA` layers 0 and 2 — `p30` → `web/data/plan.json` | six areas (MCH, HUDA, CDA, HADA, HMR, HMR growth corridor), 51 mandal polygons; service created 2025-04-17; ~22 m simplification | VERIFIED at 14 known places; specific areas overlap at boundary slivers only (0.8% of grid points) | Verify | says which plan governs, NOT what a plot is zoned for; undated; HMDA jurisdiction reportedly widened in 2025 |\n"
           "| **HMWSSB mapped network** | TGRAC `TCUR` layers 32 (supply), 39 (core-city sewer), 36 (sections) — `p32` → `web/data/network.json` (~100 m cells, 944 KB) | 215,506 supply and 90,298 sewer segments in the box (214,808 / 90,298 in use); 110 sections; service created 2025-05-24 | VERIFIED: independent recomputation at six places agrees within about 4% per window, diameters differ in 2 of 82 cells | Verify | a mapped pipe is not a connection; no mapped pipe is not 'no supply'; sewer is core city only; pipe geometry not redistributed; `ENABLED` flag and 1900-01-01 abandon dates ignored |\n")
    s = s.replace(anchor, new + anchor)
    old = "| TGRAC `Bhunaksha_Cadastral` / `DLS` parcel layers | survey-number parcels exist for peri-urban villages (e.g. Medchal) but **none inside core GHMC**; layer `ULB_Cadastral_Prohibited` has no documented meaning, so it is not presented as a legal restriction | PARTIALLY VERIFIED |"
    assert s.count(old) == 1
    s = s.replace(old, "| TGRAC `Bhunaksha_Cadastral` layer 0 | **now integrated** (section A). The earlier note 'none inside core GHMC' was wrong: survey parcels cover the former HUDA / CDA / HADA wards; the gap is the old MCH core (only a placeholder polygon). The `30cm` layer, `DLS` base cadastral and `HMDA` cadastral / pocket layers returned nothing in the box and are not used | VERIFIED |")
    old = "| HMDA master plan | hmda.gov.in did not respond to our probe | UNAVAILABLE (not checked further) |"
    assert s.count(old) == 1
    s = s.replace(old, "| HMDA master plans | hmda.gov.in is reachable (it did not respond at the first probe, so availability is intermittent). Official plans exist as **static documents**: Master Plan 2031 as about 30 mandal JPEG sheets (23-29 MB, 2021), the Revised Development Plan of the erstwhile MCH area as 7 circle PDFs (~29 MB, 2022), a zoning-regulations PDF; HUDA / HADA / CDA plans are listed but were not opened. Not georeferenced; no vector layer found. Only HEAD requests were made (nothing downloaded) | CONFIRMED to exist; NOT machine-readable |")
    old = "| TGRAC `SRO` (Buildings with Price, Road Type) | no hits at 5 test points; coverage unclear | PARTIALLY VERIFIED |"
    assert s.count(old) == 1
    s = s.replace(old, "| TGRAC `SRO` (Circle, Buildings with Price 40,589 polygons, Road Type) | no hits at 8 test points; service created 2025-07-31; coverage unclear | PARTIALLY VERIFIED |\n| OpenCity 'core city sewer lines' and HMWSSB water-connection CSVs | listed by search results only (sewer GeoJSON public domain, PM Gati Shakti source; connections are monthly applied / approved tables, not spatial); not opened | LEAD |\n| Telangana prohibited-property (Section 22-A) register | reported by secondary sources to have no single downloadable file, to have contained many wrongly listed parcels and to be under revision; not reached | CANNOT BE VERIFIED |")
    s += ("- **Parcel layer:** `SNo` is a village serial, not a survey number; `Parcel_num` is. Blank-`Parcel_num` polygons are village placeholders or the old-city placeholder and are never matched. About 1% of numbers are flagged duplicate or unreadable at source and can never produce a 'verified' match.\n"
          "- **Line layers:** `OBJECTID` is not unique (404 distinct values over 481 lines in one box); the real key is `OBJECTID_12`. `returnCountOnly` over-counts lines, so completeness is checked geometrically. Polygon tiles are checked against the server count exactly.\n"
          "- **Water network:** independent recomputation (exact shapely clipping against each cell, raw unsimplified geometry) at six places: 82 cells compared, window totals within about 4%, worst single cell 59 m, diameter mismatches 2 of 82.\n"
          "- **Missing-data safety:** each optional data file was removed in turn; six findings (`nala`, `inund`, `lost`, `choke`, `landfill`, `f_jobs`) used to read good or concern when their data was absent and now read 'data not loaded'.\n")
    return s
edit("docs/DATA_REGISTER.md", reg)

def inv(s):
    s = s.replace("| Piped water and sewerage coverage | Unavailable | HMWSSB publishes billing/connection data, not matched to places | |",
                  "| Mapped HMWSSB supply pipe near the pin | Implemented | TGRAC TCUR supply-line layer in ~100 m cells | a mapped pipe is not a connection; mapping uneven; undated |\n| Mapped sewer line near the pin | Partial | TGRAC core-city sewer layer | core city only |\n| HMWSSB operating section | Implemented | TGRAC section polygons | names the office area, not a connection |\n| Water connection, supply hours, tanker dependence | Unavailable | no public per-address record found | |")
    old = "| Survey-number / parcel identity | **Unavailable in GHMC** | cadastral parcels exist only for peri-urban villages | owner layers deliberately not used |\n| Master-plan land use, layout permissions, utility approvals | Unavailable | | ask HMDA with the survey number |"
    assert s.count(old) == 1
    s = s.replace(old, "| Plot identity (survey parcel) | Partial | TGRAC cadastral outlines; statuses verified / approximate / no match / source unavailable; manual survey number and village | survey-number level, not house plot; old city core unavailable; outline is not a legal boundary |\n| Listed in a state prohibitory-land layer | Partial | TGRAC 'ULB_Cadastral_Prohibited' (656 parcels in the box) | NOT the legal register; undocumented basis and date |\n| Which official plan governs this area | Implemented | TGRAC HMDA authority areas + official plan links | says which plan, not the zone |\n| Mapped features overlapping the parcel outline | Implemented | cadastral outline vs disappeared-tank, forest and tank layers | only for an unambiguous match; sampled, 3% minimum |\n| Master-plan land use / zoning | Unavailable | official plans are PDF / JPEG sheets | not read by SETU |\n| Layout permissions, utility approvals | Unavailable | | ask HMDA with the survey number |")
    s = s.replace("| Missing-data coverage dashboard | Planned | suggested in review |", "| Evidence-quality registry and internal dashboard (`quality.html`) | Implemented | every source and finding with observation date, service date, resolution, coverage, licence, validation, freshness, scope and removal impact; generated matrix in `EVIDENCE_MATRIX.md` | internal |\n| 'Applies to' scope tags, 'why incomplete' list, property-identity card | Implemented | | |")
    return s
edit("docs/FACTOR_INVENTORY.md", inv)

def val(s):
    s = s.replace("`node tests/engine.test.js` (4,230 checks)", "`node tests/engine.test.js` (4,680 checks)")
    s += """
## 7. Batch 4 (parcels, planning, water network, evidence quality), 24 Oct 2026
- **Tests:** 4,680 pass (433 new): registry integrity and enumerations; freshness rules; the engine cannot emit an unregistered finding; honesty invariants over 150 places (no high confidence on unvalidated or failed sources, 'unavailable' never rated, no-data never rated, scope present); **each optional data file removed in turn** (17 groups) with no dependent finding left rated and the source listed under 'why incomplete'; planning authority at 14 known places and overlap rate; 40 synthetic parcel cases (ambiguous addresses, neighbouring parcels, sub-survey numbers, flagged numbers, overlapping outlines, near-edge pins, road features, no parcels, failed or missing data); 592 real parcels matched at an interior point with their own number and village (575 verified, 17 outside the old grid bound before a bug was found and fixed); old-city core honestly unavailable; every parcel tile equals the server count; overlap detection with injected footprints (over half, touching, 1% sliver, forest); prohibitory layer quoting and wording; network integrity, sections and wording.
- **Bugs found by this batch's own checks:** my first coverage scan stored failed requests as zero (flat zero everywhere); `SNo` misread as the survey number; non-unique `OBJECTID` merging distinct pipes (22% lost in one dense tile); the server's line count over-counting; parcel tile grid reaching past the study box so edge pins were called 'outside'; six findings reading reassuring when their data file was missing.
- **Independent recomputation:** water network at six places (see DATA_REGISTER section E).
- **Not validated:** parcel outline positional accuracy (unpublished), the prohibitory layer's legal meaning, authority-area boundary dates, network completeness outside the places checked.
"""
    return s
edit("docs/VALIDATION_SAMPLE.md", val)
print("docs patched")
